"use client";

import { useState } from "react";
import { useCartStore } from "@/stores/cart-store";

export function QuantityPicker({ max }: { max: number }) {
  const [quantity, setQuantity] = useState(1);
  const add = useCartStore((state) => state.add);
  return (
    <div className="flex items-center gap-2">
      <button onClick={() => setQuantity((q) => Math.max(1, q - 1))} aria-label="One fewer">−</button>
      <output aria-live="polite">{quantity}</output>
      <button onClick={() => setQuantity((q) => Math.min(max, q + 1))} aria-label="One more">+</button>
      <button onClick={() => add(quantity)}>Add to cart</button>
    </div>
  );
}

import { notFound } from "next/navigation";
import { QuantityPicker } from "@/components/quantity-picker";
import { formatPrice } from "@/lib/format";
import { getProduct } from "@/lib/products";

export default async function ProductPage({ params }: PageProps<"/products/[slug]">) {
  const { slug } = await params;
  const product = await getProduct(slug);
  if (!product) notFound();

  return (
    <article>
      <h1 className="text-2xl font-semibold">{product.name}</h1>
      <p>{formatPrice(product.priceCents)}</p>
      <p>{product.description}</p>
      {product.inStock ? <QuantityPicker max={Math.min(product.stock, 10)} /> : <p>Out of stock</p>}
    </article>
  );
}

