"use client";

import { createContext, use, useState } from "react";
import { createStore, useStore } from "zustand";

type CartState = {
  count: number;
  add: (quantity: number) => void;
};

type CartStore = ReturnType<typeof createCartStore>;

function createCartStore(initialCount: number) {
  return createStore<CartState>()((set) => ({
    count: initialCount,
    add: (quantity) => set((state) => ({ count: state.count + quantity })),
  }));
}

const CartStoreContext = createContext<CartStore | null>(null);

export function CartStoreProvider({ initialCount, children }: { initialCount: number; children: React.ReactNode }) {
  const [store] = useState(() => createCartStore(initialCount));
  return <CartStoreContext value={store}>{children}</CartStoreContext>;
}

export function useCartStore<T>(selector: (state: CartState) => T): T {
  const store = use(CartStoreContext);
  if (!store) throw new Error("useCartStore must be used inside CartStoreProvider");
  return useStore(store, selector);
}

